<?php

namespace webcoder31\ezxmldsig\Tests;

use PHPUnit\Framework\TestCase as BaseTestCase;
use ReflectionClass;
use RobRichards\XMLSecLibs\XMLSecurityKey;
use webcoder31\ezxmldsig\XMLDSigToken;

/**
 * Base class of the test suite: paths to the test certificates (generated by
 * bin/gen-test-certs) and helpers to build tokens with them.
 */
abstract class TestCase extends BaseTestCase
{
    /** Password of tests/fixtures/certs/sign.key.pem. */
    const SIGN_KEY_PASSWORD = 'signKeyPassword';

    /** Subject DN of tests/fixtures/certs/intermediate.cert.pem, as returned
    by openssl_x509_parse(). */
    const INTERMEDIATE_DN = [
        'C'  => 'DK',
        'ST' => 'Jylland',
        'O'  => 'Lothbrok Ltd',
        'OU' => 'Shield Wall Dept',
        'CN' => 'www.lothbrok.dk',
        'emailAddress' => 'ivar@lothbrok.dk',
    ];

    /**
     * Returns the path of a file of tests/fixtures/certs/.
     */
    protected static function cert($name)
    {
        return __DIR__ . '/fixtures/certs/' . $name;
    }

    /**
     * Returns sample token data.
     */
    protected static function sampleData()
    {
        return [
            'name' => 'Ragnar Lothbrok',
            'role' => 'Jarl',
            'location' => 'Kattegat',
        ];
    }

    /**
     * Skips the current test when the installed xmlseclibs performs symmetric
     * encryption with the mcrypt extension and that extension is not loaded
     * (mcrypt left PHP core in PHP 7.2; xmlseclibs uses OpenSSL from 3.0).
     */
    protected function requireSymmetricEncryption()
    {
        if (extension_loaded('mcrypt'))
        {
            return;
        }
        $source = file_get_contents((new ReflectionClass(XMLSecurityKey::class))->getFileName());
        if (strpos($source, "'library'] = 'mcrypt'") !== false)
        {
            $this->markTestSkipped(
                'The installed xmlseclibs encrypts with the mcrypt extension, which this PHP lacks.'
            );
        }
    }

    /**
     * Creates a signed (not encrypted) token with the test signing
     * certificate.
     */
    protected static function createToken(array $data)
    {
        return XMLDSigToken::createXMLToken(
            $data,
            self::cert('sign.key.pem'),
            self::cert('sign.cert.pem'),
            self::SIGN_KEY_PASSWORD
        );
    }

    /**
     * Creates a signed and encrypted token with the test signing and
     * encryption certificates. The encryption key has no password.
     */
    protected function createSecureToken(array $data)
    {
        $this->requireSymmetricEncryption();


        return XMLDSigToken::createSecureXMLToken(
            $data,
            self::cert('sign.key.pem'),
            self::cert('sign.cert.pem'),
            self::cert('crypt.key.pem'),
            self::cert('crypt.cert.pem'),
            self::SIGN_KEY_PASSWORD,
            null
        );
    }
}
